private val extraDictionary=extraRows2.mapValues {(_,row)->extraKeys2.zip(row.split('|')).toMap()}
fun extraTranslation(text:String,language:String):String? = if(text !in extraKeys2)null else if(language=="ru")text else extraDictionary[language]?.get(text) ?: extraDictionary.getValue("en").getValue(text)
fun extraText(text:String,language:String)=extraTranslation(text,language) ?: text
